  String body='{"attributes":{"category":"north","type":"marker"},"title":"seed"}';
  MapEnvelope plain=(MapEnvelope)JSON.deserialize(body,MapEnvelope.class);
  MapEnvelope strict=(MapEnvelope)JSON.deserializeStrict(body,MapEnvelope.class);
  TextEnvelope text=(TextEnvelope)JSON.deserialize('{"attributes":"text"}',TextEnvelope.class);
  Wrapper nested=(Wrapper)JSON.deserialize('{"item":'+body+'}',Wrapper.class);
  List<MapEnvelope> listValue=(List<MapEnvelope>)JSON.deserialize('['+body+']',List<MapEnvelope>.class);
  MapEnvelope nullable=(MapEnvelope)JSON.deserialize('{"attributes":null}',MapEnvelope.class);
  MapEnvelope absent=(MapEnvelope)JSON.deserialize('{}',MapEnvelope.class);
  Account record=(Account)JSON.deserialize('{"attributes":{"type":"Account"},"Name":"row"}',Account.class);
  SObject genericRecord=(SObject)JSON.deserialize('{"attributes":{"type":"Account"},"Name":"row"}',SObject.class);
  Map<String,Object> out=new Map<String,Object>();
  out.put('plainCategory',plain.attributes==null?null:plain.attributes.get('category'));
  out.put('plainType',plain.attributes==null?null:plain.attributes.get('type'));
  out.put('strictCategory',strict.attributes==null?null:strict.attributes.get('category'));
  out.put('textField',text.attributes);
  out.put('nestedCategory',nested.item.attributes==null?null:nested.item.attributes.get('category'));
  out.put('listCategory',listValue[0].attributes==null?null:listValue[0].attributes.get('category'));
  out.put('title',plain.title);
  out.put('nullAttributes',nullable.attributes==null);
  out.put('absentAttributes',absent.attributes==null);
  out.put('recordName',record.Name);
  out.put('recordType',String.valueOf(record.getSObjectType()));
  out.put('recordHasMetadataField',record.getPopulatedFieldsAsMap().containsKey('attributes'));
  out.put('genericRecordType',String.valueOf(genericRecord.getSObjectType()));
  return JSON.serialize(out);
 }
}

